/**
 * Файл. Глобальная таблица ``files`` в ``platform_shared``.
 * 
 * Доступ к байтам проверяет ``FileGate`` по принципалу, не менеджер.
 * ``s3_key`` и ``storage_id`` пишутся в таблицу и не попадают в JSON ответа.
 */
export interface FileRecord {
    /**
     * Уникальный ID файла в системе
     */
    "file_id": string;
    /**
     * Оригинальное имя файла
     */
    "original_name": string;
    /**
     * Ключ файла в S3
     */
    "s3_key": string;
    /**
     * Хранилище байтов: platform или storage_id компании
     */
    "storage_id": string;
    /**
     * Прямой URL источника файла для proxy-download
     */
    "storage_url"?: string | null | undefined;
    /**
     * MIME тип файла
     */
    "content_type": string;
    /**
     * Размер файла в байтах
     */
    "file_size": number;
    /**
     * SHA-256 hex содержимого файла (как при upload в core.files.api)
     */
    "checksum"?: string | null | undefined;
    "status"?: FileStatus | undefined;
    /**
     * ID пользователя который загрузил
     */
    "uploaded_by"?: string | null | undefined;
    /**
     * ID компании владельца файла
     */
    "company_id"?: string | null | undefined;
    /**
     * Дополнительные метаданные файла
     */
    "metadata"?: Record<string, JsonValue> | undefined;
    /**
     * Теги для категоризации
     */
    "tags"?: string[] | undefined;
    /**
     * Доступен ли файл без авторизации
     */
    "is_public"?: boolean | undefined;
    /**
     * Same-origin download URL сервиса, который создал FileRecord (`/{segment}/api/v1/files/download/{file_id}`).
     */
    "download_url"?: string | null | undefined;
    /**
     * Время создания файла
     */
    "created_at"?: string | undefined;
    /**
     * Время обновления файла
     */
    "updated_at"?: string | undefined;
    /**
     * FileSourceKind записи
     */
    "source_kind"?: string | undefined;
    /**
     * Каталог Документов; NULL только у exempt-источников
     */
    "catalog_id"?: string | null | undefined;
    /**
     * NFC casefold original_name для уникальности в каталоге
     */
    "name_key"?: string | null | undefined;
    /**
     * Корзина Документов
     */
    "deleted_at"?: string | null | undefined;
    "deleted_by_user_id"?: string | null | undefined;
    "authz_synced_at"?: string | null | undefined;
    /**
     * Канонический FileRetentionKind для audit и purge
     */
    "retention_kind"?: string | null | undefined;
    /**
     * None только для permanent (ttl_seconds=0)
     */
    "expires_at"?: string | null | undefined;
    /**
     * Длительность аудио в миллисекундах
     */
    "duration_ms"?: number | null | undefined;
    /**
     * Язык аудио (ru, en, ...)
     */
    "language"?: string | null | undefined;
    /**
     * Частота дискретизации в Гц
     */
    "sample_rate"?: number | null | undefined;
    /**
     * Количество аудио каналов (1, 2)
     */
    "channels"?: number | null | undefined;
    /**
     * Формат аудио (mp3, wav, ogg)
     */
    "audio_format"?: string | null | undefined;
    /**
     * Текущий статус расшифровки аудио.
     */
    "transcription_status"?: AudioTranscriptionStatus | undefined;
    /**
     * Результат распознавания речи.
     */
    "transcription_text"?: string | null | undefined;
    /**
     * Текст ошибки расшифровки.
     */
    "transcription_error"?: string | null | undefined;
    /**
     * Идентификатор STT-провайдера, обработавшего аудио.
     */
    "transcription_provider"?: string | null | undefined;
    [key: string]: unknown;
}

